const TOOL_API = (window.NOESIS_API_URL || "http://localhost:7860/api/sessions").replace(/\/api\/sessions\/?$/, "") + "/api/tools";
const TOOL_IMAGE_TYPES = new Set(["jpg", "jpeg", "png", "webp"]);
const TOOL_BATCH_SIZE = 16;
const TOOL_BATCH_BYTE_LIMIT = 60 * 1024 * 1024;
const TOOL_DATA_CACHE = new Map();
const TOOL_DATA_INFLIGHT = new Map();
const CLOSE_ON_ESCAPE = true;

function markToolkitMetric(name) {
  if (!window.performance?.mark) return;
  requestAnimationFrame(() => {
    try {
      performance.mark(name);
      if (!performance.getEntriesByName("neosis-app-start", "mark").length) performance.mark("neosis-app-start");
      performance.measure(`${name}-from-app-start`, "neosis-app-start", name);
    } catch (_) {}
  });
}

function ToolkitIcon({ name="label", size=22 }) {
  const paths={label:<><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8m-8 4h5"/></>,extract:<><path d="M12 3v12m-5-5 5 5 5-5M5 21h14"/></>,upload:<><path d="M12 16V4m-5 5 5-5 5 5"/><path d="M5 14v6h14v-6"/></>,testing:<><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 15-5-5L5 20"/></>,packshots:<><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="M3 8v10l9 5 9-5V8M12 13v10"/></>,dashboard:<><path d="M4 19V5m0 14h16M8 15l3-4 3 2 5-7"/></>,accuracy:<><path d="M6 3h9l4 4v14H6z"/><path d="M14 3v5h5m-9 5 2 2 4-4"/></>,settings:<><circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a7.8 7.8 0 0 1-1.4.8l-.3 1.8h-2.8l-.3-1.8a7.8 7.8 0 0 1-1.4-.8l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-1.7l-1.4-1.1 1.4-2.4 1.7.7a7.8 7.8 0 0 1 1.4-.8l.3-1.8h2.8l.3 1.8a7.8 7.8 0 0 1 1.4.8l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1 0 1.6Z"/></>,check:<path d="m5 12 4 4L19 6"/>,edit:<><path d="m15 5 4 4M4 20l4-.8L19 8a2.1 2.1 0 0 0-3-3L5 16l-1 4Z"/></>,arrow:<path d="M5 12h14m-6-6 6 6-6 6"/>,folder:<><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z"/></>,box:<><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="M3 8v9l9 5 9-5V8M12 13v9"/></>,chip:<><rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 9h6v6H9zM9 2v4m6-4v4m-6 12v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/></>,download:<><path d="M12 3v12m-5-5 5 5 5-5"/><path d="M5 20h14"/></>,file:<><path d="M7 3h7l5 5v13H7z"/><path d="M14 3v5h5"/></>,close:<path d="m6 6 12 12M18 6 6 18"/>};
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]||paths.label}</svg>;
}

function resolveToolkitImageUrl(url) {
  if (!url) return "";
  if (/^https?:\/\//i.test(url)) return url;
  const apiOrigin = TOOL_API.replace(/\/api\/tools\/?$/, "");
  return new URL(url, `${apiOrigin}/`).toString();
}

async function toolJson(url, options = {}) {
  const response = await fetch(url, options);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) { const error=new Error(data.detail || `Request failed (${response.status})`);error.status=response.status;throw error; }
  return data;
}

function invalidateToolCache(brandSlug) {
  for (const key of TOOL_DATA_CACHE.keys()) {
    if (key.endsWith("/brands") || !brandSlug || key.includes(`/testing/${encodeURIComponent(brandSlug)}/images`) || key.includes(`/packshots/${encodeURIComponent(brandSlug)}`)) TOOL_DATA_CACHE.delete(key);
  }
}

async function refreshToolCache(url, cached) {
  if (TOOL_DATA_INFLIGHT.has(url)) return TOOL_DATA_INFLIGHT.get(url);
  const request = (async () => {
    const headers = new Headers();
    if (cached?.etag) headers.set("If-None-Match", cached.etag);
    const response = await fetch(url, { headers });
    if (response.status === 304 && cached) return cached.data;
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.detail || `Request failed (${response.status})`);
    TOOL_DATA_CACHE.set(url, { data, etag: response.headers.get("ETag") || "" });
    return data;
  })().finally(() => TOOL_DATA_INFLIGHT.delete(url));
  TOOL_DATA_INFLIGHT.set(url, request);
  return request;
}

async function cachedToolJson(url, onUpdate) {
  const cached = TOOL_DATA_CACHE.get(url);
  if (cached) {
    refreshToolCache(url, cached).then(data => onUpdate?.(data)).catch(() => {});
    return cached.data;
  }
  return refreshToolCache(url, null);
}

function uploadBatches(files) {
  const result = [];
  let batch = [], bytes = 0;
  for (const file of files) {
    if (batch.length && (batch.length >= TOOL_BATCH_SIZE || bytes + file.size > TOOL_BATCH_BYTE_LIMIT)) {
      result.push(batch); batch = []; bytes = 0;
    }
    batch.push(file); bytes += file.size;
  }
  if (batch.length) result.push(batch);
  return result;
}

function imageFiles(files) {
  return Array.from(files || []).filter(file => TOOL_IMAGE_TYPES.has(file.name.split(".").pop().toLowerCase()));
}

function cleanFolderPath(file) {
  const path = file.webkitRelativePath || file.name;
  const parts = path.split("/");
  return (parts.length > 1 ? parts.slice(1) : parts).join("/");
}

function normalizeImageName(value) {
  return String(value || "").replace(/\\/g, "/").split("/").pop().replace(/\.[^.]+$/, "").trim().toLowerCase();
}

function assetLabel(slug, assetNames) {
  if (!slug || slug === "all") return "";
  if (slug === "general") return "General";
  return assetNames?.[slug] || slug.replace(/-/g, " ");
}

function AppSelect({ value, onChange, options, placeholder="Choose an option", ariaLabel="Choose an option", style={} }) {
  const [open,setOpen]=React.useState(false), [active,setActive]=React.useState(0), [position,setPosition]=React.useState(null);
  const triggerRef=React.useRef(null), menuRef=React.useRef(null), optionRefs=React.useRef([]);
  const selected=options.find(option=>String(option.value)===String(value));
  const usable=options.filter(option=>!option.disabled);
  function close(restore=false){setOpen(false);if(restore)triggerRef.current?.focus();}
  function openMenu(){const r=triggerRef.current.getBoundingClientRect(),h=Math.min(280,window.innerHeight-24),menuH=Math.min(h,options.length*42+12),below=window.innerHeight-r.bottom>=menuH+8,top=below?r.bottom+6:Math.max(12,r.top-menuH-6);setPosition({left:Math.max(12,Math.min(r.left,window.innerWidth-r.width-12)),top:below?top:undefined,bottom:below?undefined:window.innerHeight-r.top+6,width:r.width,maxHeight:h});setActive(Math.max(0,usable.findIndex(o=>String(o.value)===String(value))));setOpen(true);}
  React.useEffect(()=>{if(open)optionRefs.current[active]?.focus();},[open,active]);
  React.useEffect(()=>{if(!open)return;const update=()=>{const r=triggerRef.current?.getBoundingClientRect();if(r)setPosition(p=>p?{...p,left:Math.max(12,Math.min(r.left,window.innerWidth-r.width-12)),top:p.bottom===undefined?r.bottom+6:undefined,bottom:p.bottom===undefined?undefined:window.innerHeight-r.top+6,width:r.width}:p);};const outside=e=>{if(!triggerRef.current?.contains(e.target)&&!menuRef.current?.contains(e.target))close();};window.addEventListener("resize",update);window.addEventListener("scroll",update,true);document.addEventListener("pointerdown",outside);return()=>{window.removeEventListener("resize",update);window.removeEventListener("scroll",update,true);document.removeEventListener("pointerdown",outside);};},[open]);
  function keyDown(e,index=-1){if(e.key==="Escape"){e.preventDefault();e.stopPropagation();close(true);return;}if(e.key==="Tab"){close();return;}if(["ArrowDown","ArrowUp","Home","End"].includes(e.key)){e.preventDefault();if(!open)openMenu();else if(e.key==="Home")setActive(0);else if(e.key==="End")setActive(Math.max(0,usable.length-1));else setActive((index+(e.key==="ArrowDown"?1:usable.length-1))%usable.length);}if((e.key==="Enter"||e.key===" ")&&index>=0){e.preventDefault();const option=usable[index];if(option){onChange(option.value);close(true);}}}
  const firstAction=options.findIndex(option=>option.action);
  return <><button ref={triggerRef} type="button" className="neosis-select-trigger" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} onClick={()=>open?close():openMenu()} onKeyDown={e=>keyDown(e,-1)} style={style}><span>{selected?.label||placeholder}</span><span className={`neosis-select-chevron${open?" open":""}`} aria-hidden="true">⌄</span></button>{open&&position&&ReactDOM.createPortal(<div ref={menuRef} className="neosis-select-menu" role="listbox" aria-label={ariaLabel} style={{position:"fixed",left:position.left,top:position.top,bottom:position.bottom,width:position.width,maxHeight:position.maxHeight,overflowY:"auto",zIndex:8000}}>{options.map((option,optionIndex)=>{const index=usable.indexOf(option),isSelected=String(option.value)===String(value);return <React.Fragment key={String(option.value)}>{optionIndex===firstAction&&optionIndex>0&&<div className="neosis-select-separator" role="separator"/>}<button ref={node=>{if(index>=0)optionRefs.current[index]=node;}} type="button" role="option" aria-selected={isSelected} disabled={option.disabled} className={`neosis-select-option${option.action?" action":""}`} onMouseEnter={()=>index>=0&&setActive(index)} onClick={()=>{if(!option.disabled){onChange(option.value);close(true);}}} onKeyDown={e=>keyDown(e,index)}><span>{option.label}</span>{isSelected&&<ToolkitIcon name="check" size={16}/>}</button></React.Fragment>;})}</div>,document.body)}</>;
}

function ToolNotice({ error, success }) {
  if (error) return <div className="tool-notice error" role="alert"><ToolkitIcon name="accuracy" size={18}/><span>{error}</span></div>;
  if (success) return <div className="tool-notice success" role="status"><ToolkitIcon name="check" size={18}/><span>{success}</span></div>;
  return null;
}

function ToolkitViewer({ image, images, onClose, getUrl, getTitle }) {
  const closeRef=React.useRef(null), opener=React.useRef(document.activeElement), index=images.findIndex(item=>item===image);
  const [current,setCurrent]=React.useState(Math.max(0,index));
  React.useEffect(()=>{const old=document.body.style.overflow;document.body.style.overflow="hidden";closeRef.current?.focus();const key=e=>{if(e.key==="Escape"&&CLOSE_ON_ESCAPE)onClose();else if(e.key==="ArrowRight")setCurrent(i=>(i+1)%images.length);else if(e.key==="ArrowLeft")setCurrent(i=>(i+images.length-1)%images.length);else if(e.key==="Tab"){e.preventDefault();closeRef.current?.focus();}};document.addEventListener("keydown",key);return()=>{document.removeEventListener("keydown",key);document.body.style.overflow=old;opener.current?.focus?.();};},[]);
  const active=images[current]||image;
  return ReactDOM.createPortal(<div className="toolkit-lightbox" role="dialog" aria-modal="true" aria-label="Image preview"><button ref={closeRef} type="button" aria-label="Close preview" onClick={onClose}>×</button><button type="button" aria-label="Previous image" onClick={()=>setCurrent(i=>(i+images.length-1)%images.length)}>‹</button><div><img src={getUrl(active)} alt={getTitle(active)} fetchPriority="high" decoding="async"/><strong>{getTitle(active)}</strong><small>{current+1} / {images.length}</small></div><button type="button" aria-label="Next image" onClick={()=>setCurrent(i=>(i+1)%images.length)}>›</button></div>,document.body);
}

function AssetFilter({ assets, assetNames, assetCounts, value, onChange }) {
  const [open,setOpen]=React.useState(false),[query,setQuery]=React.useState(""),[active,setActive]=React.useState(0),[position,setPosition]=React.useState(null);
  const triggerRef=React.useRef(null),menuRef=React.useRef(null),searchRef=React.useRef(null),optionRefs=React.useRef([]);
  const selected=Array.isArray(value)?value.filter(item=>item!=="all"):(value&&value!=="all"?[value]:[]);
  const current=selected.length===1?assetLabel(selected[0],assetNames):"";
  const visible=assets.filter(slug=>`${assetLabel(slug,assetNames)} ${slug}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  function updatePosition(){const rect=triggerRef.current?.getBoundingClientRect();if(!rect)return;const width=Math.min(360,window.innerWidth*.92),maxHeight=Math.min(320,window.innerHeight-24),left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12)),below=window.innerHeight-rect.bottom>=Math.min(maxHeight,assets.length*42+100)+8;setPosition({left,width,maxHeight,top:below?rect.bottom+6:undefined,bottom:below?undefined:window.innerHeight-rect.top+6});}
  function openMenu(){setQuery("");updatePosition();setActive(Math.max(0,visible.findIndex(slug=>slug===selected[0])));setOpen(true);}
  function closeMenu(restore=false){setOpen(false);if(restore)triggerRef.current?.focus();}
  function choose(slug){onChange(value===slug?"all":slug);closeMenu();}
  React.useEffect(()=>{if(open)searchRef.current?.focus();},[open]);
  React.useEffect(()=>{if(!open)return;const outside=e=>{if(!triggerRef.current?.contains(e.target)&&!menuRef.current?.contains(e.target))closeMenu();};const reposition=()=>updatePosition();document.addEventListener("pointerdown",outside);window.addEventListener("resize",reposition);window.addEventListener("scroll",reposition,true);return()=>{document.removeEventListener("pointerdown",outside);window.removeEventListener("resize",reposition);window.removeEventListener("scroll",reposition,true);};},[open]);
  function handleKey(event,index=-1){if(event.key==="Escape"){event.preventDefault();event.stopPropagation();closeMenu(true);return;}if(event.key==="Tab"){closeMenu();return;}if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();if(index===-2){const next=Math.max(0,Math.min(visible.length-1,event.key==="ArrowDown"?0:visible.length-1));setActive(next);requestAnimationFrame(()=>optionRefs.current[next]?.focus());}else{const next=(index+(event.key==="ArrowDown"?1:visible.length-1))%Math.max(1,visible.length);setActive(next);optionRefs.current[next]?.focus();}}if(event.key==="Home"||event.key==="End"){event.preventDefault();const next=event.key==="Home"?0:Math.max(0,visible.length-1);setActive(next);optionRefs.current[next]?.focus();}}
  const triggerLabel=selected.length>1?`Filter by asset · ${selected.length}`:current||"Filter by asset";
  return <div className="asset-filter-control"><button ref={triggerRef} type="button" className={`clay-btn-secondary asset-filter-button${selected.length?" active":""}`} aria-haspopup="listbox" aria-expanded={open} title={current||"Filter by asset"} onClick={()=>open?closeMenu():openMenu()} onKeyDown={event=>{if(["Enter"," ","ArrowDown"].includes(event.key)){event.preventDefault();open?closeMenu():openMenu();}}}><ToolkitIcon name="testing" size={16}/><span className="asset-filter-label">{triggerLabel}</span></button>{selected.length>0&&<button type="button" className="asset-filter-clear" aria-label="Clear asset filter" title="Clear filter" onClick={()=>onChange("all")}>×</button>}{open&&position&&ReactDOM.createPortal(<div ref={menuRef} className="asset-filter-popover" style={{position:"fixed",left:position.left,top:position.top,bottom:position.bottom,width:position.width,maxHeight:position.maxHeight}}><input ref={searchRef} className="asset-filter-search" type="search" value={query} placeholder="Search assets" aria-label="Search assets" onChange={event=>{setQuery(event.target.value);setActive(0);}} onKeyDown={event=>handleKey(event,-2)}/><button type="button" className="asset-filter-all" aria-pressed={selected.length===0} onClick={()=>{onChange("all");closeMenu();}}>All assets<span>{Object.values(assetCounts||{}).reduce((sum,count)=>sum+Number(count||0),0)}</span></button><div className="asset-filter-options" role="listbox" aria-label="Assets">{visible.map((slug,index)=><button ref={node=>{optionRefs.current[index]=node;}} type="button" role="option" aria-selected={selected.includes(slug)} className="asset-filter-option" key={slug} title={assetLabel(slug,assetNames)} onMouseEnter={()=>setActive(index)} onClick={()=>choose(slug)} onKeyDown={event=>handleKey(event,index)}><span className="asset-filter-checkbox" aria-hidden="true">{selected.includes(slug)?"✓":""}</span><span className="asset-filter-option-label">{assetLabel(slug,assetNames)}</span><span className="asset-filter-count">{assetCounts?.[slug]||0}</span></button>)}{!visible.length&&<div className="asset-filter-empty">No assets match this search.</div>}</div></div>,document.body)}</div>;
}

function ToolPageShell({ Shell, title, titleContent, subtitle, children, onToggleTheme, onBack, backLink, actions }) {
  return <Shell title={title} titleContent={titleContent} subtitle={subtitle} backLink={backLink || (onBack && <button className="neosis-back-link" onClick={onBack}>← Back to tools</button>)} actions={actions} onToggleTheme={onToggleTheme} showSteps={false}>{children}</Shell>;
}

const TOOL_CARDS = [
  { title:"Pseudo Labelling", description:"Run a model over a folder of images and review the predicted labels, class by class.", icon:"label", route:"#/labeler" },
  { title:"Image Extraction", description:"Turn a column of image links in an Excel or CSV file into a ZIP of downloaded images.", icon:"extract", route:"#/extract", utility:true },
  { title:"Testing Images", description:"Browse test images by brand, filter by asset, and add new images for the team.", icon:"testing", route:"#/testing-images", utility:true },
  { title:"Packshots", description:"Reference packshots for each brand, with annotation names, names and IDs.", icon:"packshots", route:"#/packshots", utility:true },
  { title:"Model Dashboard", description:"Track model versions and accuracy for every brand in one place.", icon:"dashboard", route:"#/model-dashboard" },
  { title:"Accuracy Report", description:"Generate an accuracy report for a model against the standard image set.", icon:"accuracy", route:"#/accuracy-report" },
];

function HomePage({ Shell, onToggleTheme }) {
  const cards=TOOL_CARDS;
  const [query,setQuery]=React.useState("");
  React.useEffect(()=>{const update=event=>setQuery(event.detail||"");window.addEventListener("ir-search",update);return()=>window.removeEventListener("ir-search",update);},[]);
  const matches=card=>!query.trim()||`${card.title} ${card.description}`.toLowerCase().includes(query.trim().toLowerCase());
  const core=cards.filter(card=>!card.utility&&matches(card)), utilities=cards.filter(card=>card.utility&&matches(card));
  const firstName=(window.IR_USER?.name||"").trim().split(/\s+/)[0];
  const welcomeCopy=`Welcome to Neosis${firstName?", "+firstName:""}. Choose a workflow to get started.`;
  return <ToolPageShell Shell={Shell} title="Dashboard" subtitle={welcomeCopy} onToggleTheme={onToggleTheme}>
    {core.length>0&&<section className="dashboard-section" aria-labelledby="core-workflows-title"><h2 id="core-workflows-title" className="dashboard-section-title"><ToolkitIcon name="box" size={20}/>Core Workflows</h2><div className="dashboard-core-grid">
      {core.map(card=><button key={card.title} onClick={()=>{window.location.hash=card.route;}} className="clay-card clay-card-interactive dashboard-workflow" type="button"><span className="dashboard-workflow-top"><span className="dashboard-icon" aria-hidden="true"><ToolkitIcon name={card.icon} size={20}/></span><strong>{card.title}</strong></span><small>{card.description}</small></button>)}
    </div></section>}
    {utilities.length>0&&<section className="dashboard-section dashboard-utilities" aria-labelledby="utilities-title"><h2 id="utilities-title" className="dashboard-section-title"><ToolkitIcon name="chip" size={20}/>Utilities</h2><div className="dashboard-core-grid dashboard-utility-grid">{utilities.map(card=><button key={card.title} onClick={()=>card.route&&(window.location.hash=card.route)} className="clay-card clay-card-interactive dashboard-workflow" type="button"><span className="dashboard-workflow-top"><span className="dashboard-icon" aria-hidden="true"><ToolkitIcon name={card.icon} size={20}/></span><strong>{card.title}</strong></span><small>{card.description}</small></button>)}</div></section>}
    {!core.length&&!utilities.length&&<div className="clay-card dashboard-empty"><h2>No tools match “{query}”</h2><p>Try another search term.</p></div>}
  </ToolPageShell>;
}
function ComingSoonPage({ Shell, onToggleTheme, title }) {
  return <ToolPageShell Shell={Shell} title={title} subtitle="This workspace is coming soon." onToggleTheme={onToggleTheme} backLink={<button className="neosis-back-link" onClick={()=>{window.location.hash="#/";}}>? Dashboard</button>}><section className="clay-card dashboard-empty" aria-live="polite"><h2>{title} is coming soon</h2><p>This workspace is not available yet.</p></section></ToolPageShell>;
}

